True def transform(grid):
    if not grid:
        return []
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    solid_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    solid_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    for r in solid_rows:
        for c in range(w):
            out[r][c] = 2
    for c in solid_cols:
        for r in range(h):
            out[r][c] = 2
    return out
